#!/usr/bin/env python3
"""Deterministic runtime integrity manifest. No data alteration or scientific re-admission."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1]
def build(root=R):
 def descriptor(name,tier=None):
  raw=(root/name).read_bytes();d={'path':name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
  if tier:d.update(nside=tier,id=json.loads(raw)['id'])
  return d
 m={'schema':'salah-real-sky/diffuse-runtime-manifest/1','sourceSha256':'69f3c6ede4a730e0ca4699f5943fca59d0b203f37c4dfc4b7e6927f063250446','catalogue':descriptor('data/bright-stars.json'),'assets':{str(n):descriptor(f'data/registered-starlight/V-nside{n}.json',n) for n in [32,64,128]}}
 raw=(json.dumps(m,indent=2)+'\n').encode();out=root/'data/registered-starlight/runtime-manifest.json';out.write_bytes(raw)
 digest=hashlib.sha256(raw).hexdigest();(root/'src/diffuse-manifest-pin.mjs').write_text('// Generated by tools/build_cp75_manifest.py. Integrity anchor, not an upstream signature.\nexport const DIFFUSE_MANIFEST_SHA256='+json.dumps(digest)+';\n')
 return {'path':str(out.relative_to(root)),'sha256':digest,'assets':len(m['assets'])}
if __name__=='__main__':print(json.dumps(build(),indent=2))
